import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';

// --- MODAL: Sur Place / À Emporter ---
const OrderModal = ({ isOpen, onClose, onConfirm, itemName }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md p-4">
      <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full text-center shadow-2xl">
        <h3 className="text-2xl font-black text-gray-900 italic uppercase mb-2">Mode de Commande</h3>
        <p className="text-orange-600 font-bold mb-8 text-xs tracking-widest uppercase">{itemName}</p>
        <div className="space-y-4">
          <button onClick={() => onConfirm('Sur Place')} className="w-full py-4 bg-gray-100 hover:bg-orange-600 hover:text-white text-gray-900 rounded-2xl font-black uppercase tracking-widest transition-all">🍽️ Sur Place</button>
          <button onClick={() => onConfirm('À Emporter')} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-orange-600 transition-all">🛍️ À Emporter</button>
        </div>
        <button onClick={onClose} className="mt-6 text-gray-400 font-bold text-[10px] uppercase tracking-widest hover:text-red-500 transition">Annuler</button>
      </div>
    </div>
  );
};

// --- NAVBAR: Rejje3na l-byed o l-ktaba Bold o l-Chbka ---
const Navbar = ({ cartCount }) => (
  <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
    <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
      <Link to="/" className="flex items-center space-x-3">
        <div className="bg-orange-600 p-2 rounded-full shadow-md">
          <img src="https://cdn-icons-png.flaticon.com/512/3655/3655682.png" className="w-5 h-5 invert" alt="logo" />
        </div>
        <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
      </Link>
      <div className="hidden md:flex space-x-8 text-[12px] font-black uppercase text-gray-800">
        <Link to="/" className="hover:text-orange-600 transition">Accueil</Link>
        <Link to="/menu" className="hover:text-orange-600 transition">Menu</Link>
        <Link to="/about" className="hover:text-orange-600 transition">À Propos</Link>
        <Link to="/contact" className="hover:text-orange-600 transition">Contact</Link>
      </div>
      <div className="flex items-center space-x-6">
        <Link to="/panier" className="relative flex items-center space-x-2 text-gray-800 hover:text-orange-600 transition">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
          </svg>
          <span className="bg-orange-600 text-white text-[10px] font-bold rounded-full h-5 w-5 flex items-center justify-center">{cartCount}</span>
        </Link>
        <Link to="/login" className="bg-gray-900 text-white px-6 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-orange-600 transition">Connexion</Link>
      </div>
    </div>
  </nav>
);

// --- LAYOUT: Background Chfaf ---
const PageLayout = ({ children, title }) => (
  <div className="relative min-h-screen">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/50 backdrop-blur-[4px]"></div>
    </div>
    <div className="relative z-10 max-w-7xl mx-auto px-6 py-16">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-5xl md:text-7xl font-black text-white italic tracking-tighter uppercase drop-shadow-2xl">{title}</h2>
          <div className="h-1.5 w-20 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- HOME: Rejje3na les Commentaires ---
const Home = () => (
  <PageLayout>
    <div className="text-center py-16">
      <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl leading-none">Fast<span className="text-orange-600">Délice</span></h1>
      <p className="text-xl text-white mb-12 font-black italic max-w-xl mx-auto opacity-90">"La passion du goût, l'élégance du service."</p>
      <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>

      <div className="mt-40 grid grid-cols-1 md:grid-cols-3 gap-8 text-center">
        {[
          {n: "YOUSSEF", t: "Meilleure pizza Margherita de la ville!"},
          {n: "SANAA", t: "Service ultra rapide et emballage top."},
          {n: "KARIM", t: "Les saveurs sont vraiment authentiques."}
        ].map((v, i) => (
          <div key={i} className="bg-white/10 backdrop-blur-xl p-10 rounded-[3rem] border border-white/20 hover:bg-white/20 transition-all duration-500">
             <div className="text-orange-500 mb-4 text-xs tracking-widest">★★★★★</div>
             <p className="text-white italic font-bold mb-6">"{v.t}"</p>
             <span className="text-[10px] font-black text-orange-500 uppercase tracking-widest">— {v.n}</span>
          </div>
        ))}
      </div>
    </div>
  </PageLayout>
);

// --- MENU: Added Images & Order Mode ---
const Menu = ({ categories, addToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  return (
    <PageLayout title="Menu">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {categories.flatMap(c => c.dishes).map(item => (
          <div key={item.id} className="bg-black/40 backdrop-blur-lg border border-white/10 rounded-[3rem] overflow-hidden group shadow-2xl">
            <div className="h-64 overflow-hidden relative">
              <img src={item.image || "https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=1000"} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition duration-700" />
            </div>
            <div className="p-8 text-center">
              <h3 className="text-2xl font-black text-white italic mb-2 uppercase">{item.name}</h3>
              <p className="text-orange-500 font-black text-2xl mb-6">{item.price} DH</p>
              <button onClick={() => setSelectedItem(item)} className="w-full py-4 bg-white text-black rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-orange-600 hover:text-white transition shadow-lg">Commander</button>
            </div>
          </div>
        ))}
      </div>
      <OrderModal isOpen={!!selectedItem} onClose={() => setSelectedItem(null)} onConfirm={(type) => { addToCart({...selectedItem, type}); setSelectedItem(null); }} itemName={selectedItem?.name} />
    </PageLayout>
  );
};

// --- ABOUT: 3marnaha mzyan ---
const About = () => (
  <PageLayout title="À Propos">
    <div className="max-w-4xl mx-auto bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl text-center">
      <h3 className="text-3xl font-black text-orange-600 italic mb-8 uppercase">Notre Passion</h3>
      <p className="text-white text-lg leading-relaxed font-medium italic opacity-90">
        FastDélice est né de la volonté d'offrir une cuisine de chef avec la rapidité du service moderne. 
        Chaque ingrédient est choisi avec soin pour garantir une explosion de saveurs à chaque bouchée. 
        Nous croyons que la qualité ne doit jamais être sacrifiée pour la vitesse.
      </p>
    </div>
  </PageLayout>
);

// --- PANIER: Rejje3nah o fih l-makla ---
const Panier = ({ cart }) => (
  <PageLayout title="Mon Panier">
    <div className="max-w-2xl mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
      {cart.length === 0 ? (
        <p className="text-white text-center font-bold italic opacity-60">Votre panier est vide.</p>
      ) : (
        <div className="space-y-6">
          {cart.map((item, i) => (
            <div key={i} className="flex justify-between items-center border-b border-white/10 pb-4">
              <div>
                <h4 className="text-white font-black uppercase italic">{item.name}</h4>
                <span className="text-orange-500 text-[10px] font-bold uppercase tracking-widest">{item.type}</span>
              </div>
              <span className="text-white font-black">{item.price} DH</span>
            </div>
          ))}
          <div className="pt-6 flex justify-between items-center">
            <span className="text-white text-2xl font-black uppercase">Total:</span>
            <span className="text-orange-600 text-3xl font-black">{cart.reduce((a, b) => a + parseFloat(b.price), 0)} DH</span>
          </div>
          <button className="w-full mt-8 bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">Confirmer l'achat</button>
        </div>
      )}
    </div>
  </PageLayout>
);

// --- APP ---
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/').then(res => setCategories(res.data)).catch(e => console.log(e));
  }, []);

  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={(i) => setCart([...cart, i])} />} />
          <Route path="/about" element={<About />} />
          <Route path="/panier" element={<Panier cart={cart} />} />
        </Routes>
      </div>
    </Router>
  );
}
